 L.start({leftGroups:[{type:'hum_knight',count:4}],rightGroups:[{type:'hum_levy',count:8}],deploy:false,ai:false,paused:false,morale:false,seed:7});const b=t.B; b.cmdT=1e9;b.terrain=null;b.obs=[];const g=Bgroup(true),enemy=Bgroup(false);function Bgroup(player){return Object.values(t.B.groups).find(q=>player?q.player:q.foe)}
 const make=vel=>({...g.units[0],x:500,y:500,hd:0,dir:0,vel,run:0,sta:100,s:{...g.units[0].s,spd:100}}),fast=make(100),slow=make(15);t.physGo(fast,.1,0,1,100,null,null,false);t.physGo(slow,.1,0,1,100,null,null,false);ok(fast.hd>0&&fast.hd<slow.hd&&fast.x>500&&fast.y>500,'fast horses turn on wider physical arcs than slow horses');
